import MacOsTerminal from "./mac-os-terminal"

export default function Page() {
  return <MacOsTerminal />
}

"use client"

import { Folder } from "lucide-react"
import { cn } from "@/lib/utils"

import { useTerminalAnimation } from "./hooks/use-terminal-animation"
import Spinner from "./components/spinner"
import PromptShell from "./components/prompt-shell"
import TrafficLights from "./components/traffic-lights"
import SyntaxCode from "./components/syntax-code"
import { CODE_DEMO } from "./lib/mac-os-terminal-code-segments"
import type { LineColor } from "./lib/config"

import "./styles/mac-os-terminal.css"

const codeBlockWrap = "mot-codeblock my-2 py-2 pr-2 pl-3 text-[12px] leading-[1.55]"

function colorCls(c?: LineColor) {
  if (!c) return "mot-t-line-default"
  switch (c) {
    case "green": return "mot-t-line-green"
    case "cyan":  return "mot-t-line-cyan"
    case "dim":   return "mot-t-line-dim"
  }
}

export default function MacOsTerminal() {
  const { lines, typed, phase, codeIdx, scrollRef } = useTerminalAnimation()

  return (
    <div className="mot-terminal mot-terminal-shell w-full overflow-hidden rounded-md">
      <div className="mot-terminal-titlebar relative flex h-8 shrink-0 select-none items-center">
        <TrafficLights />
        <div className="mot-terminal-title flex w-full items-center justify-center gap-1.5 px-20 text-center font-sans text-[12px] font-medium tracking-tight">
          <Folder size={14} className="size-3.5 shrink-0" fill="#3b8eea" stroke="none" strokeWidth={0} aria-hidden />
          <span>Projects</span>
          <span className="text-[#a1a1aa] dark:text-[#6b6b6b]" aria-hidden>—</span>
          <span>-zsh</span>
          <span className="text-[#a1a1aa] dark:text-[#6b6b6b]" aria-hidden>—</span>
          <span className="tabular-nums">80×24</span>
        </div>
      </div>

      <div
        ref={scrollRef}
        className="mot-terminal-body h-[32rem] overflow-y-auto px-4 py-2.5 text-left font-mono text-[13px] leading-relaxed"
        style={{ scrollbarWidth: "none" }}
      >
        {lines.map((line) => (
          <div key={line.id} className={cn("mot-terminal-line-in", colorCls(line.color))}>
            {line.spinning ? (
              <span><Spinner /> {line.text}</span>
            ) : (
              line.text || "\u00A0"
            )}
          </div>
        ))}

        {(phase === "typingCode" || phase === "done") && (
          <div className={codeBlockWrap}>
            <pre className="m-0 whitespace-pre-wrap break-words font-mono">
              <SyntaxCode visibleChars={phase === "done" ? CODE_DEMO.length : codeIdx} />
              {phase === "typingCode" && <span className="mot-terminal-cursor" />}
            </pre>
          </div>
        )}

        {(phase === "idle" || phase === "typing") && (
          <div className="flex min-w-0 flex-wrap items-center gap-x-1 gap-y-0">
            <PromptShell />
            <span className="min-w-0">{typed}</span>
            <span className="mot-terminal-cursor" />
          </div>
        )}

        {phase === "done" && (
          <div className="mt-2 flex items-center gap-x-1">
            <PromptShell />
            <span className="mot-terminal-cursor" />
          </div>
        )}
      </div>
    </div>
  )
}

/* mac-os-terminal — scoped so consumers need not import app globals */


.mot-terminal {
  --mot-t-shell-bg: #fafafa;
  --mot-t-body-bg: #ffffff;
  --mot-t-body-fg: #3f3f46;
  --mot-t-border: rgb(0 0 0 / 0.1);
  --mot-t-ring: rgb(0 0 0 / 0.06);
  --mot-t-shadow: 0 20px 40px -12px rgb(0 0 0 / 0.12);
  --mot-t-titlebar-bg: #ececec;
  --mot-t-titlebar-border: rgb(0 0 0 / 0.08);
  --mot-t-title-fg: #3c3c3c;
  --mot-t-line-green: #15803d;
  --mot-t-line-cyan: #0f766e;
  --mot-t-line-dim: #71717a;
  --mot-terminal-cursor-bg: #27272a;
}

.dark .mot-terminal {
  --mot-t-shell-bg: #1e1e1e;
  --mot-t-body-bg: #1e1e1e;
  --mot-t-body-fg: #cccccc;
  --mot-t-border: rgb(255 255 255 / 0.1);
  --mot-t-ring: rgb(0 0 0 / 0.2);
  --mot-t-shadow: 0 20px 40px -12px rgb(0 0 0 / 0.45);
  --mot-t-titlebar-bg: #2d2d2d;
  --mot-t-titlebar-border: rgb(255 255 255 / 0.08);
  --mot-t-title-fg: #d4d4d8;
  --mot-t-line-green: #16c60c;
  --mot-t-line-cyan: #61d6d6;
  --mot-t-line-dim: #767676;
  --mot-terminal-cursor-bg: #cccccc;
}

.mot-terminal-shell {
  border: 1px solid var(--mot-t-border);
  background-color: var(--mot-t-shell-bg);
  box-shadow: var(--mot-t-shadow);
  outline: 1px solid var(--mot-t-ring);
  outline-offset: -1px;
}

.mot-terminal-titlebar {
  border-bottom: 1px solid var(--mot-t-titlebar-border);
  background-color: var(--mot-t-titlebar-bg);
}

.mot-terminal-title {
  color: var(--mot-t-title-fg);
}

.mot-terminal-body {
  background-color: var(--mot-t-body-bg);
  color: var(--mot-t-body-fg);
}

.mot-t-line-default {
  color: var(--mot-t-body-fg);
}

.mot-t-line-green {
  color: var(--mot-t-line-green);
}

.mot-t-line-cyan {
  color: var(--mot-t-line-cyan);
}

.mot-t-line-dim {
  color: var(--mot-t-line-dim);
}

.mot-terminal-cursor {
  display: inline-block;
  width: 8px;
  height: 1em;
  margin-left: 1px;
  vertical-align: text-bottom;
  background-color: var(--mot-terminal-cursor-bg);
  animation: mot-terminal-blink 1.15s step-start infinite;
}

@keyframes mot-terminal-blink {
  0%,
  49.9% {
    opacity: 1;
  }
  50%,
  100% {
    opacity: 0;
  }
}

.mot-terminal-line-in {
  animation: mot-terminal-line-fade 0.12s ease-out both;
}

@keyframes mot-terminal-line-fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.mot-terminal-body::-webkit-scrollbar {
  display: none;
}

/* Syntax highlight panel — token colors swap via CSS vars on .dark */

.mot-codeblock {
  --mot-sh-kw: #b83280;
  --mot-sh-str: #166534;
  --mot-sh-fn: #6d28d9;
  --mot-sh-num: #0369a1;
  --mot-sh-prop: #18181b;
  --mot-sh-var: #0e7490;
  --mot-sh-punct: #a21caf;
  --mot-cursor-fg: #27272a;

  border-left-width: 2px;
  border-left-style: solid;
  border-left-color: rgb(59 142 234 / 0.55);
  background-color: rgb(244 244 245 / 0.95);
}

.dark .mot-codeblock {
  --mot-sh-kw: #ff79c6;
  --mot-sh-str: #50fa7b;
  --mot-sh-fn: #bd93f9;
  --mot-sh-num: #8be9fd;
  --mot-sh-prop: #f8f8f2;
  --mot-sh-var: #8be9fd;
  --mot-sh-punct: #ff79c6;
  --mot-cursor-fg: #cccccc;

  border-left-color: rgb(59 142 234 / 0.45);
  background-color: rgb(0 0 0 / 0.55);
}

.mot-sh-kw {
  color: var(--mot-sh-kw);
}
.mot-sh-str {
  color: var(--mot-sh-str);
}
.mot-sh-fn {
  color: var(--mot-sh-fn);
}
.mot-sh-num {
  color: var(--mot-sh-num);
}
.mot-sh-prop {
  color: var(--mot-sh-prop);
}
.mot-sh-var {
  color: var(--mot-sh-var);
}
.mot-sh-punct {
  color: var(--mot-sh-punct);
}

.mot-codeblock .mot-terminal-cursor {
  background-color: var(--mot-cursor-fg);
}
